arguments.command:
set -u
http_body=$(mktemp /tmp/opencode/openblog-http.XXXXXX)
https_body=$(mktemp /tmp/opencode/openblog-https.XXXXXX)
http_hdr=$(mktemp /tmp/opencode/openblog-http-headers.XXXXXX)
https_hdr=$(mktemp /tmp/opencode/openblog-https-headers.XXXXXX)
trap 'rm -f "$http_body" "$https_body" "$http_hdr" "$https_hdr"' EXIT
printf '%s
' '=== HTTP GET (no redirects) ==='
curl --verbose --silent --show-error --max-time 20 --connect-timeout 10 --dump-header "$http_hdr" --output "$http_body" --write-out 'exit=%{exitcode} curl_error=%{errormsg}
http_code=%{http_code}
url_effective=%{url_effective}
url_redirect=%{redirect_url}
remote_ip=%{remote_ip}
remote_port=%{remote_port}
size_download=%{size_download}
content_type=%{content_type}
' 'http://openblog.com/content/personal-memory-export' 2>&1
printf '%s
' 'HTTP captured headers:'
if [ -s "$http_hdr" ]; then tr -d '' < "$http_hdr"; else printf '%s
' '(none)'; fi
printf '%s
' 'HTTP artifact:'
stat --format='size=%s bytes' "$http_body"
sha256sum "$http_body"
printf '%s
' '=== HTTPS GET (no redirects) ==='
curl --verbose --silent --show-error --max-time 20 --connect-timeout 10 --dump-header "$https_hdr" --output "$https_body" --write-out 'exit=%{exitcode} curl_error=%{errormsg}
http_code=%{http_code}
url_effective=%{url_effective}
url_redirect=%{redirect_url}
remote_ip=%{remote_ip}
remote_port=%{remote_port}
size_download=%{size_download}
content_type=%{content_type}
' 'https://openblog.com/content/personal-memory-export' 2>&1
printf '%s
' 'HTTPS captured headers:'
if [ -s "$https_hdr" ]; then tr -d '' < "$https_hdr"; else printf '%s
' '(none)'; fi
printf '%s
' 'HTTPS artifact:'
stat --format='size=%s bytes' "$https_body"
sha256sum "$https_body"
printf '%s
' '=== cleanup check ==='
for f in "$http_body" "$https_body" "$http_hdr" "$https_hdr"; do [ ! -e "$f" ] && printf '%s removed
' "$f" || printf '%s STILL EXISTS
' "$f"; done

